    min_r = min_c = None
    max_r = max_c = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                if min_r is None:
                    min_r = max_r = i
                    min_c = max_c = j
                else:
                    min_r = min(min_r, i)
                    max_r = max(max_r, i)
                    min_c = min(min_c, j)
                    max_c = max(max_c, j)

    # assume there is exactly one rectangular block of 1's
    H = max_r - min_r + 1
    W = max_c - min_c + 1

    # internal 4 pattern inside the original block
    internal = []
    for i in range(min_r, max_r + 1):
        for j in range(min_c, max_c + 1):
            if grid[i][j] == 4:
                internal.append((i - min_r, j - min_c))

    # rotated pattern (90 deg clockwise)
    rot_pattern = [(c, H - 1 - r) for (r, c) in internal]

    # function to check if a candidate placement is free of conflicting cells
    def is_free(top, left, newH, newW):
        if top < 0 or top + newH > n or left < 0 or left + newW > m:
            return False
        for dr in range(newH):
            for dc in range(newW):
                val = grid[top + dr][left + dc]
                if val == 1:
                    return False
                if val == 4:
                    # 4 is allowed only if it coincides with the rotated pattern
                    if (dr, dc) not in rot_pattern:
                        return False
        return True

