    # first try rows below the block that contain a 4 on the right side
    anchor = None
    for i in range(max_r + 1, n):
        for j in range(m):
            if grid[i][j] == 4 and j > max_c:
                anchor = (i, j)
                break
        if anchor:
            break

    # if not found, try a left‑side anchor
    if anchor is None:
        for i in range(max_r + 1, n):
            for j in range(m):
                if grid[i][j] == 4 and j < min_c:
                    anchor = (i, j)
                    break
            if anchor:
                break

    # if still no anchor, fall back to the first 4 after the block (any side)
    if anchor is None:
        for i in range(max_r + 1, n):
            for j in range(m):
                if grid[i][j] == 4:
                    anchor = (i, j)
                    break
            if anchor:
                break

    # now try to place the rotated copy
    newH = W   # height after rotation
    newW = H   # width after rotation

    placed = False
    if anchor:
        ar, ac = anchor
        # decide side
        if ac < min_c:          # anchor on the left side
            for off in range(W + 1, 0, -1):
                left = ac + off
                for top in (ar, ar - (newH - 1)):
                    if top >= 0 and is_free(top, left, newH, newW):
                        # place the block
                        for dr in range(newH):
                            for dc in range(newW):
                                grid[top + dr][left + dc] = 1
                        for (pr, pc) in rot_pattern:
                            grid[top + pr][left + pc] = 4
                        placed = True
                        break
                if placed:
                    break
        else:                    # anchor on the right side (or in the middle)
            for off in range(W + 1, 0, -1):
                left = ac - off
                for top in (ar, ar - (newH - 1)):
                    if top >= 0 and is_free(top, left, newH, newW):
                        for dr in range(newH):
